WITH filtered AS (SELECT * FROM service_requests), valid AS (SELECT * FROM filtered WHERE created_date IS NOT NULL AND closed_date >= created_date AND resolution_hours >= 0), ranked AS (SELECT resolution_hours,ROW_NUMBER() OVER (ORDER BY resolution_hours) rn,COUNT(*) OVER () n FROM valid), fences AS (SELECT SUM(CASE WHEN rn=FLOOR((n-1)*0.25)+1 THEN resolution_hours*(1-((n-1)*0.25-FLOOR((n-1)*0.25))) WHEN rn=FLOOR((n-1)*0.25)+2 THEN resolution_hours*((n-1)*0.25-FLOOR((n-1)*0.25)) END) q1,SUM(CASE WHEN rn=FLOOR((n-1)*0.75)+1 THEN resolution_hours*(1-((n-1)*0.75-FLOOR((n-1)*0.75))) WHEN rn=FLOOR((n-1)*0.75)+2 THEN resolution_hours*((n-1)*0.75-FLOOR((n-1)*0.75)) END) q3 FROM ranked) SELECT YEAR(created_date) year,MONTH(created_date) month,COUNT(*) request_count FROM filtered WHERE created_date IS NOT NULL GROUP BY YEAR(created_date),MONTH(created_date) ORDER BY year,month;